css:
@page { size: 2.299in 1.5in; margin: 0; }
.print-format {
  padding: 0 !important;
  margin: 0 !important;
  width: 2.299in !important;
  height: 1.5in !important;
  min-height: 0 !important;
  max-height: 1.5in !important;
  overflow: hidden !important;
  -webkit-print-color-adjust: exact !important;
  print-color-adjust: exact !important;
}
.lab-sample-label {
  width: 2.299in;
  height: 1.5in;
  box-sizing: border-box;
  padding: 4px;
  overflow: hidden;
  background-color: #FFFF00;
  -webkit-print-color-adjust: exact;
  print-color-adjust: exact;
}
.lab-sample-label table {
  width: 100%;
  height: auto !important;
  border-collapse: collapse;
  table-layout: fixed;
  font-family: 'Times New Roman', Times, serif;
  font-size: 6.5px;
  line-height: 1;
  color: #000;
  background-color: #FFFFFF;
}
.lab-sample-label td {
  border: 0.5px solid #000;
  padding: 0 3px;
  height: 13px;
  line-height: 13px;
  vertical-align: middle;
  background-color: #FFFFFF;
}
.lab-sample-label td.lbl { width: 34%; font-weight: 600; white-space: nowrap; }
.lab-sample-label td.val { font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.lab-sample-label tr.file td {
  height: 22px;
  line-height: 22px;
  padding: 1px 3px;
}
.lab-sample-label tr.file td.val { font-size: 11px; font-weight: 700; }
